CREATE TABLE IF NOT EXISTS settings (id integer PRIMARY KEY CHECK(id=1), value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_attempts (state text PRIMARY KEY, session_id text NOT NULL, status text NOT NULL DEFAULT 'waiting', expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS connections (id integer PRIMARY KEY CHECK(id=1), user_id text NOT NULL, username text NOT NULL, token text NOT NULL, expires_at timestamptz NOT NULL, scopes jsonb NOT NULL DEFAULT '[]', capabilities jsonb NOT NULL DEFAULT '{}', checked_at timestamptz);
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), filename text NOT NULL, storage_name text NOT NULL UNIQUE, width integer NOT NULL, height integer NOT NULL, bytes integer NOT NULL, alt text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_plans (day date PRIMARY KEY, status text NOT NULL, count integer NOT NULL, slots jsonb NOT NULL, experiment_arm text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS posts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text text NOT NULL, alternative text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'teaching', status text NOT NULL DEFAULT 'draft',
 scheduled_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), revision integer NOT NULL DEFAULT 1,
 media_ids jsonb NOT NULL DEFAULT '[]', sources jsonb NOT NULL DEFAULT '[]', topic text NOT NULL DEFAULT '', reason text NOT NULL DEFAULT '', error text,
 provider_id text UNIQUE, container_id text, permalink text, expires_at timestamptz, generated boolean NOT NULL DEFAULT false, root_id text, plan_day date, slot integer, experiment_arm text,
 UNIQUE(plan_day,slot), CHECK(status IN ('draft','scheduled','publishing','published','blocked','unknown','cancelled','missed'))
);
CREATE INDEX IF NOT EXISTS posts_due ON posts(scheduled_at) WHERE status='scheduled';
CREATE TABLE IF NOT EXISTS revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id), revision integer NOT NULL, snapshot jsonb NOT NULL, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(post_id,revision));
CREATE TABLE IF NOT EXISTS publish_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id), revision integer NOT NULL, phase text NOT NULL, container_id text, provider_id text, error text, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ideas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text text NOT NULL, source_url text, kind text NOT NULL DEFAULT 'note', state text NOT NULL DEFAULT 'saved', note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_sources (url text PRIMARY KEY, text text NOT NULL, author text, published_at timestamptz, provider text NOT NULL, discovered_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trends (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, summary text NOT NULL, angle text NOT NULL, evidence jsonb NOT NULL, score integer NOT NULL, confidence text NOT NULL, state text NOT NULL DEFAULT 'new', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id), checkpoint text NOT NULL, source text NOT NULL DEFAULT 'api', measured_at timestamptz NOT NULL DEFAULT now(), age_hours real NOT NULL, views bigint, likes bigint, replies bigint, reposts bigint, quotes bigint, shares bigint, follows bigint, profile_visits bigint, raw jsonb NOT NULL DEFAULT '{}', UNIQUE(post_id,checkpoint,source));
CREATE TABLE IF NOT EXISTS account_metrics (day date PRIMARY KEY, followers bigint, profile_views bigint, clicks jsonb, measured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS replies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid REFERENCES posts(id), provider_id text NOT NULL UNIQUE, username text NOT NULL, text text NOT NULL, draft text NOT NULL DEFAULT '', state text NOT NULL DEFAULT 'new', classification text NOT NULL DEFAULT 'unclassified', meaningful boolean NOT NULL DEFAULT false, manual boolean NOT NULL DEFAULT false, source_url text, created_at timestamptz NOT NULL, sent_id text, error text);
CREATE TABLE IF NOT EXISTS operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, status text NOT NULL, message text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS operations_recent ON operations(created_at DESC);
CREATE TABLE IF NOT EXISTS generation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, cached_tokens integer NOT NULL DEFAULT 0, sources jsonb NOT NULL DEFAULT '[]', checks jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (week date PRIMARY KEY, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS experiments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), starts_on date NOT NULL, ends_on date NOT NULL, base_count integer NOT NULL, assignments jsonb NOT NULL, status text NOT NULL DEFAULT 'running', result jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_running_experiment ON experiments(status) WHERE status='running';
CREATE TABLE IF NOT EXISTS heartbeats (name text PRIMARY KEY, at timestamptz NOT NULL DEFAULT now());
